package com.tainted.community.blackbox;

import static com.tainted.community.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.tainted.community.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.tainted.community.blackbox.support.BlackBoxSupport.queryScalar;
import static com.tainted.community.blackbox.support.BlackBoxSupport.testId;
import static com.tainted.community.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;


/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api GET /internal/posts
 *
 * Step2 test-plan(CommunityService_listPosts.md): 파라미터 없음(RED 파라미터 0건) -> VTC 대상 없음.
 * Step2 산출물의 ATC_code400(General Bad Request)은 이 엔드포인트가 파라미터/바디를 전혀 받지 않아 실제로 트리거할 방법이 없는 제네릭 휴리스틱 제안이므로 Zero-Hallucination 원칙에 따라 제외한다 (조건 재현 불가).
 * Step3-B(analyze-auth-flow): auth_type=none, 인터셉터 없음 -> 인증 헤더 불필요.
 * Step3-C(detect-external-calls --include-di-analysis): 외부 HTTP 연동 없음(전 의존성 REAL) -> WireMock 불필요.
 * Step3-D(analyze-test-data): post 테이블 컬럼(id,user_id,title,category,content,mood_emoji,nickname,likes,created_at) 확인.
 * 리스트가 전역(비필터링) 응답이라 병렬 테스트/시드 데이터와 공존하므로, 응답 검증은 find{}로 우리가 삽입한 행만 식별하고, 정렬(ORDER BY created_at DESC) 규칙은 우리 두 행으로 스코프를 좁힌 JDBC dbAssertion으로 검증한다.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class ListPostsBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "ID", "post-a-" + testId(info),
                "ID2", "post-b-" + testId(info));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/internal-posts-list-teardown.sql", p);
        executeSqlTemplate("sql/internal-posts-list-setup.sql", p);
    }

    @Test
    void NTC_listPosts_returnsPersistedPostFields(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/internal/posts")
            .then()
                    .statusCode(200)
                    .body("find { it.userId == 'user-nimbus-a' }.title", equalTo("NIMBUS 리스트 테스트 게시글 A"))
                    .body("find { it.userId == 'user-nimbus-a' }.category", equalTo("daily"))
                    .body("find { it.userId == 'user-nimbus-a' }.content", equalTo("listPosts 테스트용 콘텐츠 A"))
                    .body("find { it.userId == 'user-nimbus-a' }.moodEmoji", equalTo("🙂"))
                    .body("find { it.userId == 'user-nimbus-a' }.nickname", equalTo("테스터A"))
                    .body("find { it.userId == 'user-nimbus-a' }.likes", equalTo(3));
        } finally {
            executeSqlTemplate("sql/internal-posts-list-teardown.sql", p);
        }
    }

    @Test
    void NTC_listPosts_containsSecondPostWithDifferentCategory(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/internal/posts")
            .then()
                    .statusCode(200)
                    .body("find { it.userId == 'user-nimbus-b' }.title", equalTo("NIMBUS 리스트 테스트 게시글 B"))
                    .body("find { it.userId == 'user-nimbus-b' }.category", equalTo("career"))
                    .body("find { it.userId == 'user-nimbus-b' }.likes", equalTo(0));
        } finally {
            executeSqlTemplate("sql/internal-posts-list-teardown.sql", p);
        }
    }

    @Test
    void NTC_listPosts_ordersNewerPostBeforeOlderPost(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/internal/posts")
            .then()
                    .statusCode(200)
                    .body("find { it.userId == 'user-nimbus-b' }.title", equalTo("NIMBUS 리스트 테스트 게시글 B"));
            org.junit.jupiter.api.Assertions.assertEquals("user-nimbus-b", queryScalar("SELECT user_id FROM post WHERE id IN (?, ?) ORDER BY created_at DESC LIMIT 1", p.get("ID2"), p.get("ID")));
        } finally {
            executeSqlTemplate("sql/internal-posts-list-teardown.sql", p);
        }
    }
}

