package com.tainted.community.blackbox;

import static com.tainted.community.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.tainted.community.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.tainted.community.blackbox.support.BlackBoxSupport.queryScalar;
import static com.tainted.community.blackbox.support.BlackBoxSupport.testId;
import static com.tainted.community.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api POST /internal/posts
 *
 * Step2 test-plan(CommunityService_createPost.md): NTC 1 + ATC_code400(General 400) 제안.
 * Step2-B(generate-vtc-from-red-params): 서비스 메서드 파라미터 레벨에서는 RED 0건(단순 DTO 전달) -> 자동 VTC 없음.
 * Step3-A(Controller/DTO 직접 분석): CreatePostRequest에 @NotBlank(userId,title,category,content,nickname), moodEmoji는 어노테이션 없음(nullable). 이 검증 애노테이션이 실질 RED이므로 NULL/EMPTY 규칙을 5개 필드 전체에 적용, content에는 WHITE_SPACE(trim 미적용 @NotBlank가 공백만 있는 값도 차단하는지)도 추가. ATC_code400 체크리스트는 이 VTC 케이스들로 충족된다.
 * Step3-B(analyze-auth-flow): auth_type=none.
 * Step3-C(detect-external-calls): 외부 HTTP 연동 없음. CommunityEventPublisher는 Kafka(non-HTTP)이므로 WireMock 대상 아님 — 테스트 환경의 실제 Kafka 브로커에 의존(Core Principle 4).
 * Step3-D(analyze-test-data): 대상 테이블 post(컬럼: id,user_id,title,category,content,mood_emoji,nickname,likes,created_at). id/likes/created_at은 서버가 생성하므로 응답 postId는 UUID(비결정) — notNullValue()만 허용, 나머지 응답 필드는 요청 리터럴과 equalTo 비교.
 * postId는 UUID(IdGenerator)로 서버가 생성하는 진짜 비결정 값이라 사전에 알 수 없다 — notNullValue()가 유일하게 정당한 예외이며, 실제 저장 값 검증은 user_id로 스코프를 좁힌 JDBC dbAssertion으로 수행한다.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class CreatePostBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "USER_ID", "createpost-user-" + testId(info));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/internal-posts-create-teardown.sql", p);
        executeSqlTemplate("sql/internal-posts-create-setup.sql", p);
    }

    @Test
    void NTC_createPost_success_dailyCategory(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"userId\": \"" + p.get("USER_ID") + "\", \"title\": \"NIMBUS 게시글 생성 테스트\", \"category\": \"daily\", \"content\": \"createPost 테스트 콘텐츠\", \"moodEmoji\": \"🙂\", \"nickname\": \"생성테스터\"}")
            .when()
                    .post("/internal/posts")
            .then()
                    .statusCode(201)
                    .body("postId", notNullValue())
                    .body("title", equalTo("NIMBUS 게시글 생성 테스트"))
                    .body("category", equalTo("daily"))
                    .body("content", equalTo("createPost 테스트 콘텐츠"))
                    .body("moodEmoji", equalTo("🙂"))
                    .body("nickname", equalTo("생성테스터"));
            org.junit.jupiter.api.Assertions.assertEquals("daily", queryScalar("SELECT category FROM post WHERE user_id = ?", p.get("USER_ID")));
            org.junit.jupiter.api.Assertions.assertEquals("0", queryScalar("SELECT likes FROM post WHERE user_id = ?", p.get("USER_ID")));
        } finally {
            executeSqlTemplate("sql/internal-posts-create-teardown.sql", p);
        }
    }

    @Test
    void NTC_createPost_success_relationshipCategory_noMoodEmojiLongContent(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"userId\": \"" + p.get("USER_ID") + "\", \"title\": \"NIMBUS 두번째 게시글\", \"category\": \"relationship\", \"content\": \"\", \"nickname\": \"생성테스터2\"}")
            .when()
                    .post("/internal/posts")
            .then()
                    .statusCode(201)
                    .body("postId", notNullValue())
                    .body("title", equalTo("NIMBUS 두번째 게시글"))
                    .body("category", equalTo("relationship"))
                    .body("content", equalTo(""))

